    const seenCursors = new Set<string>();
    let pageCount = 1;
    while (page.nextCursor !== undefined) {
      if (pageCount >= MAX_MCP_TOOL_PAGES || seenCursors.has(page.nextCursor)) {
        return yield* catalogFailed(caseId);
