      page = yield* abortablePromise(
        (signal) =>
          client.listTools({
            params: { cursor },
            options: { signal },
          }),
        () => catalogFailed(caseId),
      );
      tools.push(...page.tools);
      pageCount += 1;
    }
    return { ...page, tools };
  });

