import { Data } from "effect";

export class AskGinaAuthError extends Data.TaggedError("AskGinaAuthError")<{
  readonly message: string;
}> {}

export class AskGinaToolError extends Data.TaggedError("AskGinaToolError")<{
  readonly message: string;
  readonly tool?: string;
}> {}

export class AskGinaTransportError extends Data.TaggedError("AskGinaTransportError")<{
  readonly message: string;
  readonly cause?: unknown;
}> {}

export class AskGinaJsonArgsError extends Data.TaggedError("AskGinaJsonArgsError")<{
  readonly message: string;
}> {
  constructor(args: { readonly message: string }) {
    super(args);
    Object.defineProperty(this, "message", {
      configurable: true,
      enumerable: true,
      value: args.message,
      writable: true,
    });
  }
}

export type AskGinaError =
  | AskGinaAuthError
  | AskGinaToolError
  | AskGinaTransportError
  | AskGinaJsonArgsError;

const gradeSkillActivation = (
  evalCase: PluginEvalCase,
  observation: PluginEvalObservation,
): PluginEvalDimensionScore | undefined => {
  const expectation = evalCase.expected.skill;
  if (expectation === undefined || observation.activated_skills === undefined) return undefined;
  const activated = observation.activated_skills;
  const passed =
    expectation.kind === "none"
      ? activated.length === 0
      : activated.length === 1 && activated[0] === expectation.skill;
  return {
    score: passed ? 1 : 0,
    details: passed ? [] : ["skill activation did not match the expected plugin skill"],
  };
};

const totalResultBytes = (observation: PluginEvalObservation): number =>
  observation.tool_calls.reduce((total, call) => total + (call.result_bytes ?? 0), 0);

export const gradePluginEvalObservation = Function.dual<
  (
    observation: PluginEvalObservation,
  ) => (
    evalCase: PluginEvalCase,
  ) => Effect.Effect<PluginEvalCaseScore, PluginEvalObservationMismatchError>,
  (
    evalCase: PluginEvalCase,
    observation: PluginEvalObservation,
  ) => Effect.Effect<PluginEvalCaseScore, PluginEvalObservationMismatchError>
>(2, (evalCase, observation) =>
  Effect.gen(function* () {
    if (evalCase.id !== observation.case_id) {
      return yield* new PluginEvalObservationMismatchError({
        expectedCaseId: evalCase.id,
        observedCaseId: observation.case_id,
      });
    }

    const routing = gradeRouting(evalCase, observation);
    const argumentsScore = gradeArguments(evalCase, observation);
    const safety = gradeSafety(evalCase, observation);
    const completion = gradeCompletion(observation);
    const skillActivation = gradeSkillActivation(evalCase, observation);
    const dimensions = [routing, argumentsScore, completion];
    if (safety !== undefined) dimensions.push(safety);
    if (skillActivation !== undefined) dimensions.push(skillActivation);

    return {
      case_id: evalCase.id,
      overall_pass: dimensions.every((score) => score.score === 1),
      routing,
      arguments: argumentsScore,
      completion,
      ...(safety === undefined ? {} : { safety }),
      ...(skillActivation === undefined ? {} : { skill_activation: skillActivation }),
      latency_ms: observation.duration_ms,
      total_result_bytes: totalResultBytes(observation),
    };
  }).pipe(
    Effect.withSpan("plugin_evals.grade_observation", {
      attributes: {
        "plugin_eval.case_id": evalCase.id,
        "plugin_eval.target": observation.target,
        "plugin_eval.model": observation.model,
      },
    }),
  ),
);

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, test } from "vitest";
import { TranscriptContent, formatTranscriptJson } from "../src/components/transcript-content";

const render = (text: string, source = false, data = false) =>
  renderToStaticMarkup(createElement(TranscriptContent, { text, source, data }));

describe("transcript formatting", () => {
  test("renders headings, emphasis, lists, tables, links and fenced code", () => {
    const html = render(
      '## Market summary\n\n**AAVE** has *variable* supply.\n\n- First item\n- Second item\n\n| Asset | Price |\n| --- | --- |\n| AAVE | 100 |\n\n[Official source](https://example.com)\n\n```json\n{"price":100}\n```',
    );
    expect(html).toContain("<h2>Market summary</h2>");
    expect(html).toContain("<strong>AAVE</strong>");
    expect(html).toContain("<em>variable</em>");
    expect(html).toContain("<li>First item</li>");
    expect(html).toContain("<table>");
    expect(html).toContain("<th>Asset</th>");
    expect(html).toContain('aria-label="Message table"');
    expect(html).toContain('href="https://example.com"');
    expect(html).toContain('rel="noopener noreferrer"');
    expect(html).toContain('<pre><code class="language-json">');
  });

  test("escapes HTML and blocks active URLs and automatic external image loads", () => {
    const html = render(
      '<script>alert(1)</script>\n\n<img src="https://example.com/tracker" onerror="alert(2)">\n\n[bad](javascript:alert%281%29)\n\n![Chart](https://example.com/chart.png)\n\n[encoded](jav&#x61;script:alert%281%29)',
    );
    expect(html).not.toContain("<script>");
    expect(html).not.toContain("<img");
    expect(html).not.toContain('href="javascript:');
    expect(html).not.toContain('src="https://');
    expect(html).toContain("&lt;script&gt;");
    expect(html).toContain("Image: Chart");
    expect(html).toContain('href="https://example.com/chart.png"');
  });

  test("keeps the original Markdown and long contents available in source mode", () => {
    const text = "## Heading\n\n**Original** text\n" + "retained text ".repeat(2000);
    const html = render(text, true);
    expect(html).toContain("## Heading\n\n**Original** text");
    expect(html).not.toContain("<h2>");
    expect(html.match(/retained text /gu)).toHaveLength(2000);
  });

  test("pretty-prints JSON while preserving large numbers, escaped strings and duplicate keys", () => {
    const input =
      '{"id":[redacted:address],"note":"braces { } and \\"quotes\\"","empty":[],"same":1,"same":2}';
    const formatted = formatTranscriptJson(input);
    expect(formatted).toContain('  "id": [redacted:address],');
    expect(formatted).toContain('"note": "braces { } and \\"quotes\\""');
    expect(formatted).toContain('"empty": []');
    expect(formatted).toContain('"same": 1,\n  "same": 2');
    expect(formatTranscriptJson("[redacted:private_account]")).toBeUndefined();
    expect(formatTranscriptJson('{"incomplete":')).toBeUndefined();
    expect(render(input, false, true)).toContain('data-token="key"');
    expect(render(input, true, true)).toContain("[redacted:address]");
  });
});
